  put('m_m7', 5, 'fig', '<svg viewBox="0 0 220 154" class="lz-fig" role="img" aria-label="1辺100の正方形から幅1の帯を2本ひき、2回ひいた角の1を1回たすと99²。99²=10000−200+1=9801"><rect x="26" y="22" width="80" height="80" class="tr"/><rect x="106" y="22" width="12" height="92" class="bx"/><rect x="26" y="102" width="92" height="12" class="bx"/><rect x="106" y="102" width="12" height="12" class="fl"/><polygon points="26,22 118,22 118,114 26,114" class="dash"/><text x="66" y="66" text-anchor="middle">99²</text><text x="72" y="16" text-anchor="middle">100</text><text x="112" y="16" text-anchor="middle">1</text><text x="22" y="66" text-anchor="end">99</text><text x="126" y="30">100²=10000</text><text x="126" y="45">から帯100×1</text><text x="126" y="60">を2本ひき、</text><text x="126" y="75">重なりの1を</text><text x="126" y="90">1回たす</text><text x="110" y="142" text-anchor="middle">99² = 10000 − 200 + 1 = 9801</text></svg>');
  put('m_m7', 8, 'fig', '<svg viewBox="0 0 220 154" class="lz-fig" role="img" aria-label="連続する4つの整数 n, n+1, n+2, n+3 を、両はしどうし・内側どうしで組にかけると、どちらにも n²+3n が出る"><rect x="20" y="52" width="40" height="22" class="bx"/><text x="40" y="67" text-anchor="middle">n</text><rect x="70" y="52" width="40" height="22" class="bx"/><text x="90" y="67" text-anchor="middle">n+1</text><rect x="120" y="52" width="40" height="22" class="bx"/><text x="140" y="67" text-anchor="middle">n+2</text><rect x="170" y="52" width="40" height="22" class="bx"/><text x="190" y="67" text-anchor="middle">n+3</text><path d="M90,52 Q115,22 140,52" class="cv2"/><text x="115" y="22" text-anchor="middle">(n+1)(n+2) = n²+3n+2</text><path d="M40,74 Q115,124 190,74" class="cv"/><text x="115" y="112" text-anchor="middle">n(n+3) = n²+3n</text><text x="110" y="132" text-anchor="middle">n²+3n = M とおくと</text><text x="110" y="148" text-anchor="middle">M(M+2)+1 = (M+1)²</text></svg>');
  put('m_fact', 1, 'fig', '<svg viewBox="0 0 220 152" class="lz-fig" role="img" aria-label="6x²+9x を、たて3x(共通因数)の長方形で表すと、よこは2xと3で、3x(2x+3)"><rect x="40" y="30" width="50" height="75" class="tr"/><rect x="90" y="30" width="36" height="75" class="fl"/><rect x="40" y="30" width="86" height="75" class="ax"/><text x="65" y="71.5" text-anchor="middle">6x²</text><text x="108" y="71.5" text-anchor="middle">9x</text><text x="34" y="71.5" text-anchor="end">3x</text><text x="65" y="24" text-anchor="middle">2x</text><text x="108" y="24" text-anchor="middle">3</text><text x="138" y="46">たて = 共通</text><text x="138" y="63">因数 3x</text><text x="138" y="80">よこ = 残り</text><text x="138" y="97">2x と 3</text><text x="110" y="130" text-anchor="middle">6x² + 9x = 3x(2x + 3)</text><text x="110" y="146" text-anchor="middle">x(6x+9) は、まだ 3 がくくれる</text></svg>');
  put('m_fact', 9, 'fig', '<svg viewBox="0 0 220 152" class="lz-fig" role="img" aria-label="1辺xの正方形から1辺yの正方形を除いたL字形を、アとイに切って並べかえると、たてx−y、よこx+yの長方形になる"><rect x="12" y="28" width="50" height="80" class="tr"/><rect x="62" y="58" width="30" height="50" class="fl"/><rect x="62" y="28" width="30" height="30" class="dash"/><text x="52" y="22" text-anchor="middle">x</text><text x="77" y="47" text-anchor="middle">y²</text><text x="96" y="47">y</text><text x="9" y="72" text-anchor="end">x</text><text x="37" y="72" text-anchor="middle">ア</text><text x="77" y="87" text-anchor="middle">イ</text><line x1="100" y1="80" x2="116" y2="80" class="cv2"/><polyline points="110.6,82.6 116,80 110.6,77.4" class="cv2"/><rect x="122" y="60" width="48" height="30" class="tr"/><rect x="170" y="60" width="18" height="30" class="fl"/><text x="146" y="79" text-anchor="middle">ア</text><text x="179" y="79" text-anchor="middle">イ</text><text x="155" y="54" text-anchor="middle">x + y</text><text x="191" y="79">x−y</text><text x="110" y="130" text-anchor="middle">x² − y² = (x + y)(x − y)</text><text x="110" y="146" text-anchor="middle">=15 → (15, 1)、(5, 3) の組だけ</text></svg>');
  put('m_m8', 3, 'fig', '<svg viewBox="0 0 220 148" class="lz-fig" role="img" aria-label="面積3の正方形(1辺√3)を4つ並べると面積12の正方形になり、その1辺は√12=2√3"><rect x="24" y="26" width="45" height="45" class="tr"/><text x="46.5" y="52.5" text-anchor="middle">面積3</text><rect x="69" y="26" width="45" height="45" class="fl"/><text x="91.5" y="52.5" text-anchor="middle">面積3</text><rect x="24" y="71" width="45" height="45" class="fl"/><text x="46.5" y="97.5" text-anchor="middle">面積3</text><rect x="69" y="71" width="45" height="45" class="tr"/><text x="91.5" y="97.5" text-anchor="middle">面積3</text><text x="46.5" y="20" text-anchor="middle">√3</text><text x="91.5" y="20" text-anchor="middle">√3</text><text x="20" y="52.5" text-anchor="end">√3</text><text x="20" y="97.5" text-anchor="end">√3</text><text x="128" y="40">面積 3 が 4 つ</text><text x="128" y="57">→ 面積 12</text><text x="128" y="74">1辺 = √12</text><text x="128" y="91">= √3 + √3</text><text x="128" y="108">= 2√3</text><text x="110" y="140" text-anchor="middle">√12 = √(4×3) = √4×√3 = 2√3</text></svg>');
  put('m_m8', 7, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="数直線の2と3の間に√7≒2.646。4&lt;7&lt;9なので整数部分は2、2から√7までの長さが小数部分√7−2"><line x1="18" y1="72" x2="204" y2="72" class="ax"/><line x1="30" y1="66" x2="30" y2="78" class="ax"/><line x1="46" y1="69" x2="46" y2="75" class="ax"/><line x1="62" y1="69" x2="62" y2="75" class="ax"/><line x1="78" y1="69" x2="78" y2="75" class="ax"/><line x1="94" y1="69" x2="94" y2="75" class="ax"/><line x1="110" y1="69" x2="110" y2="75" class="ax"/><line x1="126" y1="69" x2="126" y2="75" class="ax"/><line x1="142" y1="69" x2="142" y2="75" class="ax"/><line x1="158" y1="69" x2="158" y2="75" class="ax"/><line x1="174" y1="69" x2="174" y2="75" class="ax"/><line x1="190" y1="66" x2="190" y2="78" class="ax"/><text x="30" y="90" text-anchor="middle">2</text><text x="190" y="90" text-anchor="middle">3</text><text x="110" y="88" text-anchor="middle">2.5</text><circle cx="133.3" cy="72" r="3.8" class="pt"/><text x="133.3" y="60" text-anchor="middle">√7 ≒ 2.646</text><line x1="30" y1="102" x2="133.3" y2="102" class="cv2"/><line x1="30" y1="97" x2="30" y2="107" class="cv2"/><line x1="133.3" y1="97" x2="133.3" y2="107" class="cv2"/><text x="81.7" y="119" text-anchor="middle">小数部分 = √7 − 2</text><text x="110" y="18" text-anchor="middle">2² = 4 &lt; 7 &lt; 9 = 3² より 2 &lt; √7 &lt; 3</text><text x="110" y="36" text-anchor="middle">整数部分は 2</text><text x="110" y="142" text-anchor="middle">小数部分 = もとの数 − 整数部分</text></svg>');
